#include <bits/stdc++.h>
using namespace std;
class Solution { public:
int maximumScore(vector<int>& nums, int k) {
 const long long MOD=1000000007; int n=nums.size(), mx=*max_element(nums.begin(),nums.end());
 vector<int> score(mx+1),prime(mx+1,1); prime[0]=prime[1]=0;
 for(int p=2;p<=mx;++p) if(prime[p]) {for(int j=p;j<=mx;j+=p) ++score[j]; if(1LL*p*p<=mx) for(long long j=1LL*p*p;j<=mx;j+=p) prime[j]=0;}
 vector<int> L(n),R(n),st;
 for(int i=0;i<n;++i){while(!st.empty()&&score[nums[st.back()]]<score[nums[i]]) st.pop_back(); L[i]=st.empty()?-1:st.back();st.push_back(i);}
 st.clear();for(int i=n-1;i>=0;--i){while(!st.empty()&&score[nums[st.back()]]<=score[nums[i]])st.pop_back();R[i]=st.empty()?n:st.back();st.push_back(i);}
 vector<int> order(n);iota(order.begin(),order.end(),0);sort(order.begin(),order.end(),[&](int a,int b){return nums[a]>nums[b];});
 auto power=[&](long long a,long long b){long long r=1;while(b){if(b&1)r=r*a%MOD;a=a*a%MOD;b>>=1;}return r;};
 long long ans=1;for(int i:order){long long cnt=1LL*(i-L[i])*(R[i]-i),take=min((long long)k,cnt);ans=ans*power(nums[i],take)%MOD;k-=take;if(!k)break;}return (int)ans;
}};
